#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# SCRUM-48: the handover. At the end all hosting is in Stefan's accounts: AWS, GitHub (repo +
# GHCR images), DuckDNS and Cloudflare Turnstile. Steven's host (squadmeet.duckdns.org, Syntax
# course AWS account) runs until the switch in stage 8, so there is no time without a host.
# It runs the existing wizards (setup-turnstile.sh, setup-aws.sh) at the right moment.
#
# Run it from anywhere: ./deploy/handover.sh. Safe to run again: each stage checks what is
# done already. Values are kept in .env.aws (not in git), next to those of setup-aws.sh.
# Start at a later stage after a break: START_AT=6 ./deploy/handover.sh
# Needs: aws (CLI v2), gh, jq, curl, openssl, dig, python3.
# Steps only Steven can do stop the wizard: it says what to ask him and waits.

cd "$(dirname "$0")/.."
ENV_FILE=".env.aws"
NAME="squadmeet"
OLD_REPO="GitGitRice/squadmeet"
OLD_OWNER="GitGitRice"
INSTANCE_TYPE="${INSTANCE_TYPE:-t2.micro}"

die() { printf '\n  %s✗ %s%s\n\n' "$RED" "$1" "$RESET"; exit 1; }

# Values of earlier runs (and of setup-aws.sh), so a stage can run on its own.
if [[ -f "$ENV_FILE" ]]; then
  while IFS='=' read -r key value; do
    [[ "$key" =~ ^[A-Z_][A-Z0-9_]*$ ]] && printf -v "$key" '%s' "$value"
  done < "$ENV_FILE"
fi

# note_handoff "text": one line in the Log of HANDOFF.local.md, so a break between days is safe.
note_handoff() {
  local file="HANDOFF.local.md" line
  [[ -f "$file" ]] || return 0
  line="- $(date +%F) · Stefan · SCRUM-48 handover: $1"
  awk -v line="$line" '{ print } /^## Log$/ && !done { print ""; print line; done = 1 }' \
    "$file" > "$file.tmp" && mv "$file.tmp" "$file"
  note "HANDOFF.local.md: $1"
}

# steven "what to ask him": shows the request and waits until Steven has done it.
steven() {
  printf '\n  %s%sAsk Steven:%s\n' "$BOLD" "$YELLOW" "$RESET"
  printf '%s\n' "$1" | sed 's/^/    /'
  printf '\n'
  pause "Press Enter when Steven says it is done."
}

aws_login() {
  export AWS_REGION AWS_DEFAULT_REGION="$AWS_REGION"
  if ! aws sts get-caller-identity >/dev/null 2>&1; then
    say "The AWS CLI is not logged in. A browser window opens for the AWS login."
    aws login --region "$AWS_REGION" || die "AWS login failed. Run 'aws login' by hand, then run this again."
  fi
  ACCOUNT_ID=$(aws sts get-caller-identity --query Account --output text)
}

# The four images that CI pushes (.github/workflows/ci.yml).
IMAGES=(backend frontend db deploy)
# grep without -q in pipes: -q stops reading early, and with pipefail the cut-off writer fails.
has_tag() { # has_tag <image> <tag>: the tag is in ghcr.io/<IMAGE_OWNER>/squadmeet-<image>
  gh api --paginate "users/$IMAGE_OWNER/packages/container/$NAME-$1/versions" \
    --jq '.[].metadata.container.tags[]' 2>/dev/null | grep -x "$2" >/dev/null
}

health_version() { curl -fsS --max-time 10 "https://$1/api/health" 2>/dev/null | jq -r '.version // empty'; }

# on_host "commands": runs a shell script on the new host through SSM and waits for it.
on_host() {
  local params command_id status=Pending
  params=$(jq -n --arg script "$1" '{commands: ($script | split("\n")), executionTimeout: ["1800"]}')
  command_id=$(aws ssm send-command --instance-ids "$INSTANCE_ID" --document-name AWS-RunShellScript \
    --comment "squadmeet handover" --parameters "$params" --query Command.CommandId --output text)
  for _ in $(seq 1 200); do
    sleep 10
    status=$(aws ssm get-command-invocation --command-id "$command_id" --instance-id "$INSTANCE_ID" \
      --query Status --output text 2>/dev/null || echo Pending)
    [[ "$status" =~ ^(Pending|InProgress|Delayed)$ ]] || break
    note "… $status"
  done
  aws ssm get-command-invocation --command-id "$command_id" --instance-id "$INSTANCE_ID" \
    --query '[StandardOutputContent,StandardErrorContent]' --output text | tail -n 20
  [[ "$status" == Success ]]
}

# presign_put <bucket> <key>: an upload link for one object, valid 1 hour. The AWS CLI only
# makes download links, so this signs it (AWS Signature Version 4) with the CLI's login.
presign_put() {
  aws configure export-credentials --format process | python3 -I -c '
import datetime, hashlib, hmac, json, sys, urllib.parse
creds = json.load(sys.stdin)
access_key = creds["AccessKeyId"]
bucket, key, region = sys.argv[1], sys.argv[2], sys.argv[3]
now = datetime.datetime.now(datetime.timezone.utc)
amz_date, day = now.strftime("%Y%m%dT%H%M%SZ"), now.strftime("%Y%m%d")
host = f"{bucket}.s3.{region}.amazonaws.com"
scope = f"{day}/{region}/s3/aws4_request"
query = {
    "X-Amz-Algorithm": "AWS4-HMAC-SHA256",
    "X-Amz-Credential": f"{access_key}/{scope}",
    "X-Amz-Date": amz_date,
    "X-Amz-Expires": "3600",
    "X-Amz-SignedHeaders": "host",
}
if creds.get("SessionToken"):
    query["X-Amz-Security-Token"] = creds["SessionToken"]
quote = lambda v: urllib.parse.quote(v, safe="-_.~")
canonical_query = "&".join(f"{quote(k)}={quote(v)}" for k, v in sorted(query.items()))
path = "/" + quote(key)
request = f"PUT\n{path}\n{canonical_query}\nhost:{host}\n\nhost\nUNSIGNED-PAYLOAD"
to_sign = f"AWS4-HMAC-SHA256\n{amz_date}\n{scope}\n" + hashlib.sha256(request.encode()).hexdigest()
signing_key = ("AWS4" + creds["SecretAccessKey"]).encode()
for part in (day, region, "s3", "aws4_request"):
    signing_key = hmac.new(signing_key, part.encode(), hashlib.sha256).digest()
signature = hmac.new(signing_key, to_sign.encode(), hashlib.sha256).hexdigest()
print(f"https://{host}{path}?{canonical_query}&X-Amz-Signature={signature}")
' "$1" "$2" "$AWS_REGION"
}

TOTAL_STAGES=10
START_AT="${START_AT:-1}"

banner "Squadmeet handover to Stefan (SCRUM-48)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage_1() {
  stage "Tools and your AWS account"
  for tool in aws gh jq curl openssl dig python3; do
    command -v "$tool" >/dev/null 2>&1 || die "'$tool' is missing (macOS: brew install awscli gh jq bind). Then run this again."
  done
  gh auth status >/dev/null 2>&1 || die "gh is not logged in. Run 'gh auth login', then run this again."
  ME=$(gh api user --jq .login)
  say "GitHub: you are logged in as ${BOLD}$ME${RESET}. The repo moves to this account."
  confirm "Is $ME your own GitHub account?" || die "Log in with 'gh auth login' as yourself, then run this again."
  write_env NEW_OWNER "$ME"

  ask AWS_REGION "AWS region (Enter for eu-central-1, Frankfurt):"
  AWS_REGION="${AWS_REGION:-eu-central-1}"
  write_env AWS_REGION "$AWS_REGION"
  aws_login
  say "Logged in as ${BOLD}$(aws sts get-caller-identity --query Arn --output text)${RESET}"
  say "AWS account ID: ${BOLD}$ACCOUNT_ID${RESET}"
  warn "Nothing is written to AWS before you confirm this account."
  confirm "Is $ACCOUNT_ID YOUR AWS account (not the Syntax course account)?" \
    || die "Log in to your own account ('aws login'), then run this again."
  write_env AWS_ACCOUNT_ID "$ACCOUNT_ID"

  free_tier=$(aws ec2 describe-instance-types --instance-types "$INSTANCE_TYPE" \
    --query 'InstanceTypes[0].FreeTierEligible' --output text 2>/dev/null || echo unknown)
  if [[ "$free_tier" == True ]]; then
    say "${GREEN}✓${RESET} '$INSTANCE_TYPE' is Free Tier eligible in this account."
  else
    warn "'$INSTANCE_TYPE' is not Free Tier eligible here (answer: $free_tier)."
    confirm "Use it anyway (it costs money)?" || die "Stopped. Decide the instance type, then run: INSTANCE_TYPE=<type> ./deploy/handover.sh"
  fi
  write_env INSTANCE_TYPE "$INSTANCE_TYPE"
  note_handoff "stage 1 done (AWS account confirmed, $INSTANCE_TYPE in $AWS_REGION)."
  pause
}

# ── 2 ─────────────────────────────────────────────────────────────────────
stage_2() {
  stage "Repo transfer to $NEW_OWNER"
  NEW_REPO="$NEW_OWNER/$NAME"
  current=$(gh api "repos/$OLD_REPO" --jq .full_name 2>/dev/null || true)
  if [[ "$current" != "$NEW_REPO" ]]; then
    say "Before the transfer, main must have the CI that pushes the images to the repo's owner"
    say "(this PR, SCRUM-48, released dev → main)."
    gh api "repos/$OLD_REPO/contents/.github/workflows/ci.yml?ref=main" --jq .content | base64 --decode \
      | grep 'steps.owner.outputs.name' >/dev/null \
      || die "main still has the old CI (images to ghcr.io/gitgitrice). Release dev → main first, then run this again."
    say "${GREEN}✓${RESET} main has the new CI."
    if gh api "repos/$NEW_REPO" >/dev/null 2>&1; then
      die "You have a repo $NEW_REPO already. Rename or delete it first, then run this again."
    fi
    warn "After the transfer, merges into main are not live until stage 7: Steven's deploy role"
    warn "trusts only the old repo. His host keeps the last version. Tell Steven and Dominik."
    steven "GitHub → $OLD_REPO → Settings → General → 'Danger Zone' → 'Transfer ownership'.
New owner: $NEW_OWNER. Type the repo name to confirm → 'I understand, transfer this repository'."
    say "GitHub sends you an email. Accept the transfer there (the link is valid for one day)."
    open_url "https://github.com/notifications"
    pause "Press Enter when you have accepted it."
    current=$(gh api "repos/$OLD_REPO" --jq .full_name 2>/dev/null || true)
    [[ "$current" == "$NEW_REPO" ]] || die "The repo is not at $NEW_REPO yet (GitHub says: ${current:-nothing}). Run this again when it is."
  fi
  say "${GREEN}✓${RESET} The repo is $NEW_REPO."
  write_env NEW_REPO "$NEW_REPO"
  git remote set-url origin "https://github.com/$NEW_REPO.git"
  say "${GREEN}✓${RESET} git remote 'origin' → https://github.com/$NEW_REPO.git"

  say "Checks on $NEW_REPO:"
  [[ "$(gh api "repos/$NEW_REPO/actions/permissions" --jq .enabled)" == true ]] \
    && step "Actions: on" || warn "Actions are off. Settings → Actions → General → 'Allow all actions'."
  rulesets=$(gh api "repos/$NEW_REPO/rulesets" --jq '[.[] | .name + " (" + .enforcement + ")"] | join(", ")' 2>/dev/null || true)
  [[ -n "$rulesets" ]] && step "Branch rules: $rulesets" || warn "No ruleset protects main and dev. Make one: Settings → Rules → Rulesets."
  step "Secrets: $(gh secret list -R "$NEW_REPO" --json name --jq '[.[].name] | join(", ")' 2>/dev/null || echo '?')"
  step "Variables: $(gh variable list -R "$NEW_REPO" --json name,value --jq '[.[] | .name + "=" + .value] | join(", ")' 2>/dev/null || echo '?')"
  step "Collaborators: $(gh api "repos/$NEW_REPO/collaborators" --jq '[.[].login] | join(", ")' 2>/dev/null || echo '?')"

  # Steven's deploy role trusts only the old repo; with the variable gone, CI skips the
  # deploy instead of failing. setup-aws.sh sets the new values in stage 6.
  if gh variable list -R "$NEW_REPO" --json name --jq '.[].name' | grep -x AWS_DEPLOY_ROLE_ARN >/dev/null \
     && [[ "$(gh variable get AWS_DEPLOY_ROLE_ARN -R "$NEW_REPO")" != *":$AWS_ACCOUNT_ID:"* ]]; then
    say "The deploy variables still point to Steven's host. They cannot work any more."
    if confirm "Delete AWS_DEPLOY_ROLE_ARN, EC2_INSTANCE_ID and APP_DOMAIN (CI then skips the deploy)?"; then
      for var in AWS_DEPLOY_ROLE_ARN EC2_INSTANCE_ID APP_DOMAIN; do
        gh variable delete "$var" -R "$NEW_REPO" >/dev/null 2>&1 || true
      done
      say "${GREEN}✓${RESET} deleted; stage 6 sets them for your host."
    fi
  fi
  note_handoff "stage 2 done (repo is $NEW_REPO, remote updated)."
  pause
}

# ── 3 ─────────────────────────────────────────────────────────────────────
stage_3() {
  stage "Images in your GHCR"
  IMAGE_OWNER=$(printf '%s' "$NEW_OWNER" | tr '[:upper:]' '[:lower:]')
  write_env IMAGE_OWNER "$IMAGE_OWNER"
  say "CI pushes the images to ghcr.io/$IMAGE_OWNER/$NAME-* (the repo's owner)."
  if ! gh auth status 2>&1 | grep 'read:packages' >/dev/null; then
    say "gh needs the scope read:packages to see your packages. A browser opens."
    gh auth refresh -h github.com -s read:packages || die "gh auth refresh failed."
  fi
  for branch in dev main; do
    missing=()
    for image in "${IMAGES[@]}"; do has_tag "$image" "$branch" || missing+=("$image"); done
    if (( ${#missing[@]} )); then
      say "Missing with tag '$branch': ${missing[*]}. Starting CI on $branch …"
      started=$(date -u +%Y-%m-%dT%H:%M:%SZ)
      gh workflow run ci.yml -R "$NEW_REPO" --ref "$branch" >/dev/null
      run_id=""
      for _ in $(seq 1 12); do # the new run shows up after a few seconds
        sleep 5
        run_id=$(gh run list -R "$NEW_REPO" --workflow ci.yml --branch "$branch" --event workflow_dispatch \
          --limit 1 --json databaseId,createdAt --jq ".[] | select(.createdAt >= \"$started\") | .databaseId")
        [[ -n "$run_id" ]] && break
      done
      [[ -n "$run_id" ]] || die "The CI run on $branch did not start. Look at https://github.com/$NEW_REPO/actions"
      gh run watch "$run_id" -R "$NEW_REPO" --exit-status >/dev/null \
        || die "CI on $branch failed: gh run view $run_id -R $NEW_REPO --log-failed"
    fi
    for image in "${IMAGES[@]}"; do
      has_tag "$image" "$branch" || die "ghcr.io/$IMAGE_OWNER/$NAME-$image:$branch is still missing."
    done
    say "${GREEN}✓${RESET} All four images with tag '$branch' are in your GHCR."
  done
  note "The GHCR read token for the server comes in stage 6 (setup-aws.sh): from YOUR account."
  note_handoff "stage 3 done (images dev + main in ghcr.io/$IMAGE_OWNER)."
  pause
}

# ── 4 ─────────────────────────────────────────────────────────────────────
stage_4() {
  stage "Your DuckDNS: a temporary name"
  ask FINAL_DOMAIN "The name after the switch (Enter for $NAME.duckdns.org):"
  FINAL_DOMAIN="${FINAL_DOMAIN:-$NAME.duckdns.org}"
  write_env FINAL_DOMAIN "$FINAL_DOMAIN"
  say "'${FINAL_DOMAIN%.duckdns.org}' is in Steven's DuckDNS until the switch (stage 8)."
  say "Until then your host gets a temporary name."
  open_url "https://www.duckdns.org"
  step "Sign in with YOUR account (top right, for example with GitHub)."
  step "Add a temporary sub domain, for example '$NAME-neu' → 'add domain'."
  step "Your token is at the top of the page, next to 'token'."
  ask DUCKDNS_SUBDOMAIN "Temporary subdomain (only the name):"
  DUCKDNS_SUBDOMAIN="${DUCKDNS_SUBDOMAIN%.duckdns.org}"
  [[ -n "$DUCKDNS_SUBDOMAIN" && "$DUCKDNS_SUBDOMAIN.duckdns.org" != "$FINAL_DOMAIN" ]] \
    || die "Give a temporary name, not ${FINAL_DOMAIN%.duckdns.org}."
  ask_secret DUCKDNS_TOKEN "Paste YOUR DuckDNS token:"
  [[ -n "$DUCKDNS_TOKEN" ]] || die "No token given."
  # Checks name and token. Without an IP, DuckDNS sets your current one; stage 6 changes it
  # to the server. Only the first line counts ("OK" or "KO").
  answer=$(curl -fsS "https://www.duckdns.org/update?domains=$DUCKDNS_SUBDOMAIN&token=$DUCKDNS_TOKEN" | head -n1 || true)
  [[ "$answer" == OK ]] || die "DuckDNS answered '$answer'. Check the subdomain and the token."
  DOMAIN="$DUCKDNS_SUBDOMAIN.duckdns.org"
  write_env DUCKDNS_SUBDOMAIN "$DUCKDNS_SUBDOMAIN"
  write_env DUCKDNS_TOKEN "$DUCKDNS_TOKEN"
  write_env DOMAIN "$DOMAIN"
  say "${GREEN}✓${RESET} $DOMAIN is yours. Stage 6 points it to your server."
  note_handoff "stage 4 done (temporary name $DOMAIN; $FINAL_DOMAIN at the switch)."
  pause
}

# ── 5 ─────────────────────────────────────────────────────────────────────
stage_5() {
  stage "Your Cloudflare Turnstile (captcha)"
  aws_login
  say "deploy/setup-turnstile.sh runs now. Log in to YOUR Cloudflare account there."
  say "The widget gets both names: $DOMAIN and $FINAL_DOMAIN. The keys go only into"
  say "Parameter Store of your AWS account $ACCOUNT_ID."
  pause "Press Enter to start it."
  ENV_FILE="$ENV_FILE" AWS_REGION="$AWS_REGION" DOMAIN="$DOMAIN" FINAL_DOMAIN="$FINAL_DOMAIN" \
    deploy/setup-turnstile.sh || die "The Turnstile wizard stopped (output above)."
  aws ssm get-parameter --name "/$NAME/turnstile-secret-key" >/dev/null 2>&1 \
    || die "No Turnstile keys in your Parameter Store yet. Run this stage again."
  note_handoff "stage 5 done (Turnstile keys of your widget in your SSM)."
}

# ── 6 ─────────────────────────────────────────────────────────────────────
stage_6() {
  stage "Your server (deploy/setup-aws.sh)"
  say "deploy/setup-aws.sh runs now (10 stages). It finds the values of stages 1–5."
  step "Stage 2 budget: 10 USD."
  step "Stage 3 DuckDNS: Enter keeps $DOMAIN and your token."
  step "Stage 4: the GHCR token comes from YOUR GitHub account; image owner: Enter keeps $IMAGE_OWNER."
  step "Stage 4: the Turnstile keys are stored already: answer 'N' (do not replace)."
  step "Stage 8 deploys 'main' to your server; stage 10 sets the automatic deploy for $NEW_REPO."
  pause "Press Enter to start it."
  INSTANCE_TYPE="$INSTANCE_TYPE" FINAL_DOMAIN="$FINAL_DOMAIN" deploy/setup-aws.sh \
    || die "setup-aws.sh stopped (output above). Fix it, then run: START_AT=6 ./deploy/handover.sh"
  # Read the values that setup-aws.sh wrote (INSTANCE_ID, ELASTIC_IP, …).
  while IFS='=' read -r key value; do
    [[ "$key" =~ ^[A-Z_][A-Z0-9_]*$ ]] && printf -v "$key" '%s' "$value"
  done < "$ENV_FILE"

  stage_check "$DOMAIN"
  note_handoff "stage 6 done (server $INSTANCE_ID, $ELASTIC_IP, https://$DOMAIN runs main)."
}

# stage_check <domain>: /api/health shows main's SHA, the map loads, registration works.
stage_check() {
  main_sha=$(gh api "repos/$NEW_REPO/commits/main" --jq .sha)
  version=$(health_version "$1")
  if [[ "$version" == "$main_sha" ]]; then
    say "${GREEN}✓${RESET} https://$1/api/health shows main ($main_sha)."
  else
    warn "https://$1 runs '${version:-nothing}', main is $main_sha."
    note "The tag 'main' may be older than the newest commit. Stage 7 deploys the exact SHA."
  fi
  say "Places in Leipzig: $(curl -fsS "https://$1/api/places?bbox=12.2,51.2,12.6,51.5" | jq length)"
  open_url "https://$1"
  step "The map shows Places in Leipzig."
  step "Register a test account: the Turnstile box appears and the registration works."
  confirm "Map and registration work?" || die "Not as expected. See deploy/README.md → Troubleshooting."
}

# ── 7 ─────────────────────────────────────────────────────────────────────
stage_7() {
  stage "Automatic deploy: proof"
  [[ "$(gh variable get AWS_DEPLOY_ROLE_ARN -R "$NEW_REPO" 2>/dev/null)" == *":$AWS_ACCOUNT_ID:"* ]] \
    || die "AWS_DEPLOY_ROLE_ARN does not point to your account. Run stage 6 again (setup-aws.sh stage 10)."
  say "${GREEN}✓${RESET} The deploy role of your account is set on $NEW_REPO."
  say "Proof: a merge into main deploys to your server."
  step "Merge a small PR into main (for example a release dev → main), then come back."
  pause "Press Enter after the merge."
  run_id=$(gh run list -R "$NEW_REPO" --workflow ci.yml --branch main --event push --limit 1 \
    --json databaseId --jq '.[0].databaseId')
  sha=$(gh run view "$run_id" -R "$NEW_REPO" --json headSha --jq .headSha)
  say "Watching CI run $run_id (commit $sha) …"
  gh run watch "$run_id" -R "$NEW_REPO" --exit-status >/dev/null \
    || die "The run failed: gh run view $run_id -R $NEW_REPO --log-failed"
  deploy=$(gh run view "$run_id" -R "$NEW_REPO" --json jobs \
    --jq '.jobs[] | select(.name | startswith("Deploy")) | .conclusion')
  [[ "$deploy" == success ]] || die "The deploy job ended with '${deploy:-not run}'."
  [[ "$(health_version "$DOMAIN")" == "$sha" ]] || die "https://$DOMAIN does not run $sha."
  say "${GREEN}✓${RESET} The merge deployed $sha to https://$DOMAIN by itself."
  note_handoff "stage 7 done (automatic deploy to your server proved with $sha)."
  pause
}

# ── 8 ─────────────────────────────────────────────────────────────────────
stage_8() {
  stage "Switch: $FINAL_DOMAIN to your server"
  aws_login
  if [[ "$(health_version "$FINAL_DOMAIN")" != "" && "$(dig +short "$FINAL_DOMAIN" @1.1.1.1 | tail -n1)" == "$ELASTIC_IP" ]]; then
    say "${GREEN}✓${RESET} $FINAL_DOMAIN points to your server already."
  else
    warn "From Steven's stop until the end of this stage the app is offline (a few minutes)."
    warn "Tell the team: nobody uses the app now."
    data_step
    steven "DuckDNS (his account) → delete the sub domain '${FINAL_DOMAIN%.duckdns.org}'."
    open_url "https://www.duckdns.org"
    step "YOUR DuckDNS account: add the sub domain '${FINAL_DOMAIN%.duckdns.org}'."
    pause "Press Enter when it is in your account."
    final_sub="${FINAL_DOMAIN%.duckdns.org}"
    answer=$(curl -fsS "https://www.duckdns.org/update?domains=$final_sub&token=$DUCKDNS_TOKEN&ip=$ELASTIC_IP" || true)
    [[ "$answer" == OK ]] || die "DuckDNS answered '$answer'. Is '$final_sub' in your account now? Run this stage again."
    write_env TEMP_SUBDOMAIN "$DUCKDNS_SUBDOMAIN"
    write_env DUCKDNS_SUBDOMAIN "$final_sub"
    say "Waiting until $FINAL_DOMAIN points to $ELASTIC_IP …"
    for _ in $(seq 1 30); do
      [[ "$(dig +short "$FINAL_DOMAIN" @1.1.1.1 | tail -n1)" == "$ELASTIC_IP" ]] && break
      sleep 10
    done
    [[ "$(dig +short "$FINAL_DOMAIN" @1.1.1.1 | tail -n1)" == "$ELASTIC_IP" ]] \
      || die "$FINAL_DOMAIN does not point to $ELASTIC_IP after 5 minutes. Run this stage again."
    # The domain is fixed in the SSM document (setup-deploy-document.sh) and read by CI.
    AWS_REGION="$AWS_REGION" deploy/setup-deploy-document.sh "$FINAL_DOMAIN" "$IMAGE_OWNER" \
      || die "The SSM document update failed (output above)."
    gh variable set APP_DOMAIN -R "$NEW_REPO" --body "$FINAL_DOMAIN" >/dev/null
    say "${GREEN}✓${RESET} GitHub variable APP_DOMAIN = $FINAL_DOMAIN"
    sha=$(gh api "repos/$NEW_REPO/commits/main" --jq .sha)
    AWS_REGION="$AWS_REGION" EC2_INSTANCE_ID="$INSTANCE_ID" APP_DOMAIN="$FINAL_DOMAIN" \
      deploy/deploy.sh "$sha" || die "The deploy with the new name failed (output above)."
  fi
  # A switch done earlier (or by hand) skipped the question above: ask it now.
  if [[ -z "${MOVE_DATA:-}" ]]; then
    warn "The data question was not answered at the switch. Steven's host still has the old data."
    warn "A move now replaces your database: accounts made on your server since the switch are lost."
    data_step
  fi
  DOMAIN="$FINAL_DOMAIN"
  write_env DOMAIN "$DOMAIN"
  stage_check "$FINAL_DOMAIN"
  note_handoff "stage 8 done ($FINAL_DOMAIN runs on your server; data moved: ${MOVE_DATA:-no})."
  pause
}

# data_step: asks once whether the data moves (kept as MOVE_DATA), then moves it or has Steven
# stop the old app. Either way nobody writes to the old database any more.
data_step() {
  if confirm "Move the data (users, Meetups, Ratings) from Steven's host to yours?"; then
    move_data
    MOVE_DATA=yes && write_env MOVE_DATA yes
  else
    MOVE_DATA=no && write_env MOVE_DATA no
    steven "Stop the old app, so nobody writes to it any more:
aws ssm start-session --target <his instance id>
sudo -i && cd /opt/squadmeet && docker compose stop backend web"
  fi
}

# move_data: Steven dumps the old database into a private bucket of yours through a one-hour
# upload link; your server restores it. The file never goes through a laptop, git or a chat.
move_data() {
  bucket="$NAME-transfer-$ACCOUNT_ID"
  key="$NAME-$(date +%Y%m%d%H%M).sql.gz"
  if ! aws s3api head-bucket --bucket "$bucket" >/dev/null 2>&1; then
    aws s3api create-bucket --bucket "$bucket" \
      --create-bucket-configuration LocationConstraint="$AWS_REGION" >/dev/null
    aws s3api put-public-access-block --bucket "$bucket" --public-access-block-configuration \
      BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true
  fi
  say "${GREEN}✓${RESET} Private bucket $bucket (only for this move, deleted at the end)."
  upload_url=$(presign_put "$bucket" "$key")
  say "Send Steven the upload link below directly (a private message, not a group chat)."
  note "It allows one upload of one file, for one hour. It cannot read anything."
  printf '\n%s\n\n' "$upload_url"
  steven "On the old host (aws ssm start-session --target <his instance id>):
sudo -i && cd /opt/squadmeet
docker compose stop backend web
docker compose exec -T db pg_dump -U squadmeet squadmeet | gzip > /tmp/squadmeet.sql.gz
sha256sum /tmp/squadmeet.sql.gz
curl -fsS -T /tmp/squadmeet.sql.gz '<the upload link>'
rm /tmp/squadmeet.sql.gz
Then send you the sha256 line."
  aws s3api head-object --bucket "$bucket" --key "$key" >/dev/null 2>&1 \
    || die "The file is not in $bucket yet. Run this stage again for a new link."
  ask DUMP_SHA "The first 12 characters of Steven's sha256:"
  download_url=$(aws s3 presign "s3://$bucket/$key" --expires-in 900)
  say "Restoring on your server (the backend stops for it) …"
  on_host "set -eu
cd /opt/squadmeet
curl -fsS -o /tmp/squadmeet.sql.gz '$download_url'
sha256sum /tmp/squadmeet.sql.gz | grep -q '^$DUMP_SHA' || { echo 'sha256 does not match'; exit 1; }
docker compose stop backend
docker compose exec -T db psql -U squadmeet -d postgres -v ON_ERROR_STOP=1 -c 'DROP DATABASE IF EXISTS squadmeet WITH (FORCE)' -c 'CREATE DATABASE squadmeet OWNER squadmeet TEMPLATE template0'
gunzip -c /tmp/squadmeet.sql.gz | docker compose exec -T db psql -U squadmeet -d squadmeet -v ON_ERROR_STOP=1 -q
rm -f /tmp/squadmeet.sql.gz
docker compose start backend
docker compose exec -T db psql -U squadmeet -d squadmeet -tAc 'SELECT count(*) FROM app_user'" \
    || die "The restore failed (output above). The backend may be stopped: run this stage again."
  aws s3 rm "s3://$bucket/$key" >/dev/null
  aws s3api delete-bucket --bucket "$bucket"
  say "${GREEN}✓${RESET} Data restored (the last line is the number of users); bucket deleted."
}

# ── 9 ─────────────────────────────────────────────────────────────────────
stage_9() {
  stage "Steven removes his side"
  steven "In the Syntax course AWS account ($AWS_REGION):
- EC2: terminate the instance 'squadmeet', release its Elastic IP
- Parameter Store: delete /squadmeet/* (ghcr-token, ghcr-user, postgres-password, turnstile-*)
- IAM: roles squadmeet-ec2 (+ instance profile) and squadmeet-github-deploy,
  the OIDC provider token.actions.githubusercontent.com (if nothing else uses it)
- SSM document squadmeet-deploy, security group squadmeet-web, budget squadmeet-monthly
Elsewhere:
- Cloudflare: his Turnstile widget 'squadmeet'
- GitHub: his GHCR packages ghcr.io/gitgitrice/squadmeet-* and his read:packages token
- DuckDNS: the name is in your account since stage 8"
  say "${GREEN}✓${RESET} $FINAL_DOMAIN → $(dig +short "$FINAL_DOMAIN" @1.1.1.1 | tail -n1) (your server: $ELASTIC_IP)"

  collaborators=$(gh api "repos/$NEW_REPO/collaborators" --jq '[.[].login] | join(", ")')
  say "Collaborators on $NEW_REPO: $collaborators"
  if [[ ",$collaborators," == *"$OLD_OWNER"* ]]; then
    if confirm "Remove $OLD_OWNER (Steven) from the repo?"; then
      gh api -X DELETE "repos/$NEW_REPO/collaborators/$OLD_OWNER" >/dev/null
      say "${GREEN}✓${RESET} $OLD_OWNER removed."
    else
      say "$OLD_OWNER stays a collaborator."
    fi
  fi
  if [[ -n "${TEMP_SUBDOMAIN:-}" ]]; then
    open_url "https://www.duckdns.org"
    step "Your DuckDNS: delete the temporary name '$TEMP_SUBDOMAIN'."
    step "Your Cloudflare Turnstile widget: remove the hostname $TEMP_SUBDOMAIN.duckdns.org."
    pause
  fi
  note_handoff "stage 9 done (Steven's side removed; collaborators: $collaborators)."
  pause
}

# ── 10 ────────────────────────────────────────────────────────────────────
stage_10() {
  stage "Docs and Jira"
  say "Last step: the docs name your accounts and services, and SCRUM-48 gets a comment."
  step "Ask Claude: \"SCRUM-48 Stufe 10: Doku und Jira\"."
  note "HANDOFF.md, README.md, deploy/README.md and the privacy page (/datenschutz) change"
  note "through a branch and a PR into dev."
  note_handoff "wizard finished; docs and Jira comment next (stage 10)."
  pause
}

_STAGE_INDEX=$((START_AT - 1))
for n in $(seq "$START_AT" "$TOTAL_STAGES"); do
  # A stage that runs on its own needs the account login and the values of stage 1.
  if (( n > 1 )) && [[ -z "${NEW_OWNER:-}" ]]; then die "Run stage 1 first (START_AT=1)."; fi
  "stage_$n"
done

finish
say "App:     https://${FINAL_DOMAIN:-?}"
say "Repo:    https://github.com/${NEW_REPO:-?}"
say "Server:  ${INSTANCE_ID:-?} (${ELASTIC_IP:-?}, ${AWS_REGION:-?}) in your AWS account"
printf '\n'
